//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_SPEED_TYPE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.SPEED_TYPE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.SPEED_TYPE_AIRSPEED.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.SPEED_TYPE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.SPEED_TYPE_AIRSPEED, dec)
	})
}
